    - { name: "Mathematics: Basic", base: 80, per_level: 2, note: "Printed 27: automatic, known by all characters. The educational bonus applies to skill PROGRAMS, so it is not added here." }
    - { name: "Language: Native Tongue", base: 98, note: "Printed 27: automatic - ''Speaks Native Language''." }
    - { name: "Literacy: Native Language", base: 98, note: "Printed 27: automatic - ''Read/Write Native Language''." }
  mos:
