    note: "Printed 27: select 2 skill programs. Every skill under each one is granted on top of the skills above, and the +5% educational bonus is already added to each named percentage. Printed 27 restriction 7 names the only six programs this level may take."
    options:
      - id: "computer"
        name: "Computer Program"
        skills:
          - { name: "Computer Operation", base: 65, per_level: 5 }
          - { name: "Computer Programming", base: 45, per_level: 5 }
      - id: "domestic"
        name: "Domestic Program"
        skills:
          - { choose: 3, categories: ["Domestic"], bonus: 5, note: "Printed 27: select three. The bonus adds to each row''s own base - see the class note on percentages." }
      - id: "physical"
        name: "Physical Program"
        skills:
          - { choose: 4, categories: ["Physical"], bonus: 5, note: "Printed 28: select four. Printed 27 restriction 3 allows only ONE hand to hand skill." }
      - id: "language"
        name: "Language Program"
        skills:
          - { choose: 3, categories: [{ name: "Technical", only_prefix: ["Language:"] }, { name: "Communications", only_prefix: ["Language:", "Literacy:"] }], bonus: 5, note: "Printed 28: select three. The catalog files spoken languages under Technical and literacies under Communications, so this spans both, each bounded by its own prefix." }
      - id: "technical"
        name: "Technical Program"
        skills:
